from __future__ import annotations

from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import HandleInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


class ScamShieldReportFormatter(Component):
    display_name = "ScamShield Report Formatter"
    description = (
        "Formats ScamShield structured analysis into a readable Markdown report "
        "and handles upstream model failures gracefully."
    )
    icon = "file-text"
    name = "ScamShieldReportFormatter"

    inputs = [
        HandleInput(
            name="report_data",
            display_name="Structured Report",
            input_types=["Data", "JSON"],
            required=True,
            info=(
                "Structured response produced by the "
                "ScamShield Investigation Agent."
            ),
        ),
    ]

    outputs = [
        Output(
            name="formatted_report",
            display_name="Formatted Report",
            method="format_report",
        ),
    ]

    @staticmethod
    def _as_payload(value: Any) -> dict[str, Any]:
        """
        Normalize Langflow Data or dictionary input into a plain dictionary.
        """
        if isinstance(value, Data):
            payload = value.data

        elif isinstance(value, dict):
            payload = value.get("data", value)

        else:
            raise TypeError(
                f"Unsupported report input: {type(value).__name__}. "
                "Expected Data or JSON."
            )

        if not isinstance(payload, dict):
            raise TypeError(
                "Structured report payload must be a dictionary."
            )

        return payload

    @staticmethod
    def _string(
        value: Any,
        default: str = "Tidak tersedia",
    ) -> str:
        """
        Convert any value into a safe non-empty string.
        """
        if value is None:
            return default

        text = str(value).strip()

        return text if text else default

    @staticmethod
    def _confidence(value: Any) -> str:
        """
        Convert decimal confidence such as 0.95 into 95%.
        """
        try:
            number = float(value)

        except (TypeError, ValueError):
            return ScamShieldReportFormatter._string(value)

        if 0 <= number <= 1:
            return f"{number:.0%}"

        return f"{number:g}"

    @staticmethod
    def _list(value: Any) -> list[Any]:
        """
        Normalize a scalar, list, or missing value into a list.
        """
        if value is None:
            return []

        if isinstance(value, list):
            return value

        return [value]

    @staticmethod
    def _join_values(value: Any) -> str:
        """
        Join list values into a readable comma-separated string.
        """
        values = [
            str(item).strip()
            for item in ScamShieldReportFormatter._list(value)
            if item is not None and str(item).strip()
        ]

        return ", ".join(values)

    @staticmethod
    def _is_quota_error(error_text: str) -> bool:
        """
        Detect rate-limit or quota-related upstream API errors.
        """
        normalized = error_text.lower()

        markers = (
            "429",
            "too many requests",
            "resource_exhausted",
            "quota exceeded",
            "rate limit",
            "generate_content_free_tier_requests",
        )

        return any(marker in normalized for marker in markers)

    @staticmethod
    def _is_auth_error(error_text: str) -> bool:
        """
        Detect authentication or API-key configuration errors.
        """
        normalized = error_text.lower()

        markers = (
            "401",
            "403",
            "unauthorized",
            "permission denied",
            "permission_denied",
            "api key",
            "invalid key",
            "authentication",
        )

        return any(marker in normalized for marker in markers)

    @staticmethod
    def _is_timeout_error(error_text: str) -> bool:
        """
        Detect timeout or temporary network errors.
        """
        normalized = error_text.lower()

        markers = (
            "timeout",
            "timed out",
            "deadline exceeded",
            "deadline_exceeded",
            "connection error",
            "service unavailable",
            "503",
        )

        return any(marker in normalized for marker in markers)

    def _format_error_report(
        self,
        payload: dict[str, Any],
    ) -> Message | None:
        """
        Convert an upstream structured-output failure wrapper into a
        user-friendly report instead of raising a red Langflow error.
        """
        error_text = self._string(
            payload.get("error"),
            default="",
        )

        if not error_text:
            return None

        if self._is_quota_error(error_text):
            report = """# SCAMSHIELD ID
## Analisis Belum Dapat Diproses

Layanan analisis AI sedang mencapai batas penggunaan atau kuota sementara.

Tidak ada penilaian risiko yang berhasil dihasilkan untuk kasus ini. Kegagalan layanan tidak berarti bahwa kasus telah dinilai aman.

## Tindakan Sementara

- Jangan melakukan transfer dana selama bukti belum berhasil dianalisis.
- Jangan memberikan OTP, PIN, password, kode pemulihan, atau informasi finansial sensitif.
- Verifikasi pihak terkait melalui kanal resmi yang ditemukan secara independen.
- Coba kembali ketika kuota tersedia atau gunakan model analisis lain.

> Ini merupakan gangguan layanan AI, bukan hasil penilaian terhadap bukti kasus.
"""

        elif self._is_auth_error(error_text):
            report = """# SCAMSHIELD ID
## Konfigurasi Model Bermasalah

Layanan analisis AI tidak dapat diakses karena API key, izin project, atau konfigurasi autentikasi belum valid.

Tidak ada penilaian risiko yang berhasil dihasilkan.

## Pemeriksaan yang Diperlukan

- Periksa API key pada konfigurasi model.
- Pastikan API key berasal dari project yang benar.
- Pastikan layanan Gemini API telah diaktifkan.
- Pastikan project memiliki izin dan billing yang sesuai bila diperlukan.

> Kegagalan autentikasi bukan berarti bukti kasus dinilai aman.
"""

        elif self._is_timeout_error(error_text):
            report = """# SCAMSHIELD ID
## Layanan Analisis Tidak Merespons

Permintaan analisis mengalami timeout atau gangguan koneksi sementara.

Tidak ada penilaian risiko yang berhasil dihasilkan.

## Tindakan Sementara

- Jangan melakukan transaksi atau memberikan informasi sensitif.
- Simpan seluruh bukti asli.
- Coba jalankan kembali analisis melalui koneksi yang stabil.
- Gunakan model alternatif apabila gangguan terus berlanjut.

> Gangguan teknis bukan merupakan hasil penilaian terhadap kasus.
"""

        else:
            report = """# SCAMSHIELD ID
## Analisis Gagal Diproses

Terjadi kesalahan pada layanan analisis AI atau structured response.

Tidak ada penilaian risiko yang berhasil dihasilkan. Periksa konfigurasi model, output schema, dan log komponen Agent.

## Tindakan Sementara

- Jangan menganggap kasus aman hanya karena analisis gagal.
- Jangan melakukan transfer atau memberikan informasi sensitif.
- Simpan bukti kasus dalam bentuk asli.
- Coba kembali setelah konfigurasi diperiksa.

> Kegagalan sistem bukan merupakan hasil penilaian terhadap bukti kasus.
"""

        message = Message(text=report.strip())
        self.status = message

        return message

    def _format_entities(self, entities: Any) -> str:
        """
        Format extracted entities into readable Markdown bullets.
        """
        if not isinstance(entities, dict):
            return (
                "_Tidak ada entitas terstruktur yang tersedia._"
            )

        labels = {
            "claimed_organization_names": "Organisasi yang diklaim",
            "person_names": "Nama orang",
            "platforms": "Platform",
            "bank_names": "Bank",
            "bank_accounts": "Nomor rekening",
            "account_holder_names": "Pemilik rekening",
            "transaction_amounts": "Nominal transaksi",
            "phone_numbers": "Nomor telepon",
            "urls": "URL",
            "key_timestamps": "Waktu penting",
            "disclosed_sensitive_information": (
                "Informasi sensitif yang diungkapkan"
            ),
        }

        lines: list[str] = []

        for key, label in labels.items():
            rendered = self._join_values(
                entities.get(key)
            )

            if rendered:
                lines.append(
                    f"- **{label}:** {rendered}"
                )

        if not lines:
            return (
                "_Tidak ada entitas eksplisit "
                "yang berhasil diekstraksi._"
            )

        return "\n".join(lines)

    def _format_missing_evidence(self, items: Any) -> str:
        """
        Format missing-evidence list.
        """
        values = [
            str(item).strip()
            for item in self._list(items)
            if item is not None and str(item).strip()
        ]

        if not values:
            return (
                "_Tidak ada bukti tambahan yang dinyatakan "
                "perlu diverifikasi._"
            )

        return "\n".join(
            f"- {item}"
            for item in values
        )

    def _format_indicators(self, indicators: Any) -> str:
        """
        Format detected indicators into structured Markdown sections.
        """
        values = [
            item
            for item in self._list(indicators)
            if isinstance(item, dict)
        ]

        if not values:
            return (
                "_Tidak ada indikator risiko yang terdeteksi._"
            )

        sections: list[str] = []

        for index, indicator in enumerate(
            values,
            start=1,
        ):
            name = self._string(
                indicator.get("indicator_name"),
                "UNNAMED_INDICATOR",
            )

            severity = self._string(
                indicator.get("severity")
            )

            confidence = self._confidence(
                indicator.get("confidence")
            )

            support_status = self._string(
                indicator.get("support_status")
            )

            evidence = self._string(
                indicator.get("evidence")
            )

            explanation = self._string(
                indicator.get("explanation")
            )

            section = "\n".join(
                [
                    f"### {index}. {name}",
                    f"- **Severity:** {severity}",
                    f"- **Confidence:** {confidence}",
                    (
                        "- **Support Status:** "
                        f"{support_status}"
                    ),
                    f"- **Evidence:** “{evidence}”",
                    (
                        "- **Explanation:** "
                        f"{explanation}"
                    ),
                ]
            )

            sections.append(section)

        return "\n\n".join(sections)

    def _format_actions(self, actions: Any) -> str:
        """
        Format prioritized recommended actions.
        """
        values = [
            item
            for item in self._list(actions)
            if isinstance(item, dict)
        ]

        if not values:
            return (
                "_Tidak ada tindakan yang direkomendasikan._"
            )

        def priority_value(
            item: dict[str, Any],
        ) -> int:
            try:
                return int(
                    item.get("priority", 999)
                )

            except (TypeError, ValueError):
                return 999

        values.sort(key=priority_value)

        sections: list[str] = []

        for fallback_priority, item in enumerate(
            values,
            start=1,
        ):
            priority = item.get(
                "priority",
                fallback_priority,
            )

            urgency = self._string(
                item.get("urgency")
            )

            action = self._string(
                item.get("action")
            )

            reason = self._string(
                item.get("reason")
            )

            section = "\n".join(
                [
                    (
                        f"### {priority}. "
                        f"[{urgency}] {action}"
                    ),
                    f"**Alasan:** {reason}",
                ]
            )

            sections.append(section)

        return "\n\n".join(sections)

    def format_report(self) -> Message:
        """
        Build the final Markdown report.
        """
        payload = self._as_payload(
            self.report_data
        )

        error_message = self._format_error_report(
            payload
        )

        if error_message is not None:
            return error_message

        case_id = self._string(
            payload.get("case_id")
        )

        case_stage = self._string(
            payload.get("case_stage")
        )

        incident_category = self._string(
            payload.get("incident_category")
        )

        risk_level = self._string(
            payload.get("risk_level")
        )

        overall_confidence = self._confidence(
            payload.get("overall_confidence")
        )

        summary = self._string(
            payload.get("summary")
        )

        final_recommendation = self._string(
            payload.get("final_recommendation")
        )

        safety_note = self._string(
            payload.get("safety_note")
        )

        entities = self._format_entities(
            payload.get("extracted_entities")
        )

        missing_evidence = (
            self._format_missing_evidence(
                payload.get("missing_evidence")
            )
        )

        indicators = self._format_indicators(
            payload.get("detected_indicators")
        )

        actions = self._format_actions(
            payload.get("recommended_actions")
        )

        report = f"""# SCAMSHIELD ID
## Digital Fraud Triage Report

---

| Informasi Kasus | Hasil |
|---|---|
| **Case ID** | {case_id} |
| **Case Stage** | `{case_stage}` |
| **Incident Category** | `{incident_category}` |
| **Risk Level** | **{risk_level}** |
| **Overall Confidence** | {overall_confidence} |

## Ringkasan

{summary}

## Entitas yang Diekstraksi

{entities}

## Bukti yang Belum Tersedia

{missing_evidence}

## Indikator Risiko

{indicators}

## Tindakan yang Direkomendasikan

{actions}

## Rekomendasi Akhir

{final_recommendation}

## Catatan Keselamatan

> {safety_note}
"""

        message = Message(
            text=report.strip()
        )

        self.status = message

        return message
